mapper.select:
SELECT m.id, m.tenant_id AS tenantId, m.conversation_id AS conversationId, m.sender_id AS senderId, m.msg_type AS msgType, m.content, m.extra_json AS extraJson, m.recalled, m.recalled_at AS recalledAt, m.edited, m.edited_at AS editedAt, m.reply_to_id AS replyToId, m.reply_preview AS replyPreview, COALESCE(m.reply_sender_name, ru.real_name, ru.username) AS replySenderName, m.created_at AS createdAt, COALESCE(u.real_name, u.username) AS senderName, u.avatar_url AS senderAvatar FROM chat_message m LEFT JOIN sys_user u ON u.id = m.sender_id LEFT JOIN chat_message rm ON rm.id = m.reply_to_id AND IFNULL(rm.deleted, 0) = 0 LEFT JOIN sys_user ru ON ru.id = rm.sender_id WHERE m.conversation_id = #{conversationId} AND IFNULL(m.deleted, 0) = 0
AND m.id < #{beforeId}
ORDER BY m.id DESC LIMIT #{limit}
